539	+import { rulesPresets } from "@pirate-sea-race/content";
540	+import { describe, expect, it } from "vitest";
541	+import { nextInt } from "../random.js";
542	+import {
543	+  checkFruitState,
544	+  createFruitConfig,
545	+  createFruitState,
546	+  fruitRules,
547	+  hashState,
548	+  kitOf,
549	+  replayFruits,
550	+  stepFruits,
551	+  type FruitPlayer,
