556	+} from "./index.js";
557	+
558	+/** A short meal, so random scripts finish plenty of them. */
559	+const config = createFruitConfig({ ...fruitRules, eatTicks: 8 });
560	+const SITES: FruitSite[] = ["dock-a", "dock-b", "dock-c", "dock-d"].map((id, index) => ({ id, x: index * 512, y: 0 }));
561	+/** Ids whose code-unit order differs from numeric and case-insensitive order. */
562	+const IDS = ["p1", "p10", "p2", "P3", "a", "B"];
563	+
564	+type Draw = (bound: number) => number;
565	+
566	+function generator(seed: number): Draw {
567	+  let rng = seed;
568	+  return (bound) => {
569	+    const drawn = nextInt(rng, bound);
570	+    rng = drawn.state;
571	+    return drawn.value;
572	+  };
573	+}
574	+
575	+function shuffled<T>(items: readonly T[], draw: Draw): T[] {
576	+  const copy = [...items];
577	+  for (let index = copy.length - 1; index > 0; index--) {
578	+    const other = draw(index + 1);
579	+    [copy[index], copy[other]] = [copy[other]!, copy[index]!];
580	+  }
581	+  return copy;
582	+}
583	+
584	+/**
585	+ * A seeded script: players crowd the pedestals, hold and release, get reserved, disconnect, leave for good and drop
586	+ * out of the facts; world ticks are now and then skipped or repeated. `calm` (per mille) scales how rarely anything
587	+ * changes, so some meals run to completion and some players finish together.
588	+ */
589	+function randomScript(seed: number, calm: number): FruitTickInput[] {
590	+  const draw = generator(seed);
591	+  const chance = (perMille: number) => draw(1000) < Math.floor((perMille * (1000 - calm)) / 1000);
592	+  const ids = shuffled(IDS, draw).slice(0, 2 + draw(5));
593	+  const pedestalOf = () => (draw(6) === 0 ? null : SITES[draw(2)]!.id); // two busy pedestals, crowded
594	+  const players = new Map<string, FruitPlayer>(
595	+    ids.map((playerId) => [playerId, { playerId, pedestalId: pedestalOf(), holding: true, reserved: false, disconnected: false, left: false }]),
596	+  );
597	+  const script: FruitTickInput[] = [];
598	+  let tick = 0;
599	+  for (let count = 0; count < 160; count++) {
600	+    tick += chance(15) ? 2 : 1;
601	+    for (const id of ids) {
602	+      let next = players.get(id)!;
603	+      if (chance(30)) next = { ...next, pedestalId: draw(3) === 0 ? SITES[draw(SITES.length)]!.id : pedestalOf() };
604	+      if (chance(60)) next = { ...next, holding: !next.holding };
605	+      if (chance(20)) next = { ...next, reserved: !next.reserved };
606	+      if (chance(15)) next = { ...next, disconnected: !next.disconnected };
607	+      if (chance(3)) next = { ...next, left: true };
608	+      players.set(id, next);
609	+    }
610	+    script.push({ tick, players: ids.filter(() => !chance(10)).map((id) => players.get(id)!) });
611	+    // A repeated or stale tick, which must change nothing.
612	+    if (chance(15)) script.push({ tick: tick - draw(3), players: shuffled([...players.values()], draw) });
613	+  }
614	+  return script;
615	+}
616	+
617	+interface Run {
618	+  readonly states: readonly FruitState[];
619	+  readonly hashes: readonly string[];
620	+  readonly results: readonly (readonly FruitResult[])[];
621	+}
