739	+/** Builds a match's fruit config from the content rules, refusing invalid rules. */
740	+export function createFruitConfig(rules: FruitRules = defaultFruitRules): FruitConfig {
741	+  const checked = validateFruitRules(rules);
742	+  if (!checked.ok) throw new RangeError(`invalid fruit rules: ${checked.issues.join("; ")}`);
743	+  return { eatTicks: checked.value.eatTicks };
744	+}
