795	+
796	+function requireInteger(value: unknown, name: string): void {
797	+  if (typeof value !== "number" || !Number.isSafeInteger(value)) throw new RangeError(`${name} must be a safe integer, got ${String(value)}`);
798	+}
799	+
800	+/**
801	+ * The fruit kits a match deals: `KIT_IDS` without the Duelist. A preset asking for another number of fruit kits is
802	+ * refused until its kits exist (the alpha asks for six; two exist).
803	+ */
804	+export function fruitDeck(preset: RulesPreset, pedestalsPerKit: number): FruitKitId[] {
805	+  if (preset.fruitKits !== FRUIT_KIT_IDS.length) {
806	+    throw new RangeError(
807	+      `the ${preset.id} preset deals ${preset.fruitKits} fruit kits, but only ${FRUIT_KIT_IDS.length} exist (${FRUIT_KIT_IDS.join(", ")})`,
808	+    );
809	+  }
810	+  return FRUIT_KIT_IDS.flatMap((kit) => Array.from({ length: pedestalsPerKit }, () => kit));
811	+}
