828	+  requireInteger(tick, "tick");
829	+  const checkedPreset = validateRulesPreset(preset);
830	+  if (!checkedPreset.ok) throw new RangeError(`invalid rules preset: ${checkedPreset.issues.join("; ")}`);
831	+  const rules = validateFruitRules(options.rules ?? defaultFruitRules);
832	+  if (!rules.ok) throw new RangeError(`invalid fruit rules: ${rules.issues.join("; ")}`);
833	+  const deck = fruitDeck(checkedPreset.value, rules.value.pedestalsPerKit);
834	+  if (sites.length !== deck.length) {
835	+    throw new RangeError(`the ${preset.id} preset needs ${deck.length} pedestal sites (${rules.value.pedestalsPerKit} per fruit kit), got ${sites.length}`);
836	+  }
837	+  const ids = new Set<string>();
838	+  for (const site of sites) {
839	+    if (typeof site.id !== "string" || site.id.length === 0) throw new RangeError("pedestal ids must be non-empty strings");
840	+    if (ids.has(site.id)) throw new RangeError(`pedestal ${site.id} appears twice`);
841	+    ids.add(site.id);
842	+    requireInteger(site.x, `${site.id}.x`);
843	+    requireInteger(site.y, `${site.id}.y`);
844	+  }
845	+  let rng = seed >>> 0;
846	+  for (let index = deck.length - 1; index > 0; index--) {
847	+    const drawn = nextInt(rng, index + 1);
848	+    rng = drawn.state;
849	+    [deck[index], deck[drawn.value]] = [deck[drawn.value]!, deck[index]!];
850	+  }
851	+  const pedestals = sites.map((site, index) => ({ id: site.id, x: site.x, y: site.y, kit: deck[index]!, eatenBy: null }));
852	+  return { tick, pedestals, channels: [], meals: [] };
853	+}
854	+
855	+/**
856	+ * A player's kit (§9): the fruit they ate, or the Duelist for a player who has not eaten, and for an id the state has
857	+ * never seen. Nothing in this module clears a meal, so a defeat or leaving keeps it.
858	+ */
859	+export function kitOf(state: FruitState, playerId: string): KitId {
860	+  return state.meals.find((meal) => meal.playerId === playerId)?.kit ?? "duelist";
861	+}
862	+
863	+/** What a pedestal shows: its fruit's kit and description, or that it is empty. */
864	+export type PedestalInspection =
865	+  | { readonly pedestalId: string; readonly full: true; readonly kit: FruitKitId; readonly description: KitDescription }
866	+  | { readonly pedestalId: string; readonly full: false };
867	+
868	+/**
869	+ * The kit description a player may read before committing (§9), or null for an unknown pedestal. The deal is hidden
870	+ * information: the caller shows a pedestal's kit only to players at that pedestal.
871	+ */
872	+export function inspectPedestal(state: FruitState, pedestalId: string): PedestalInspection | null {
873	+  const pedestal = state.pedestals.find((candidate) => candidate.id === pedestalId);
874	+  if (pedestal === undefined) return null;
875	+  if (pedestal.eatenBy !== null) return { pedestalId, full: false };
876	+  return { pedestalId, full: true, kit: pedestal.kit, description: kitDescriptions[pedestal.kit] };
877	+}
