884	+import { hashState } from "../hash.js";
885	+import type { FruitKitId } from "@pirate-sea-race/content/fruits";
886	+import type { FruitChannel, FruitConfig, FruitMeal, FruitPedestal, FruitState } from "./state.js";
887	+
888	+/** What the caller knows about one player on this tick. */
889	+export interface FruitPlayer {
890	+  readonly playerId: string;
891	+  /** The pedestal the player stands at (the caller decides reach), or null. */
892	+  readonly pedestalId: string | null;
893	+  /** Holding interact on this tick. */
894	+  readonly holding: boolean;
895	+  /** Reserved for, or fighting, a duel (§6). */
896	+  readonly reserved: boolean;
897	+  /** Disconnected (§12): channels are cancelled. */
898	+  readonly disconnected: boolean;
899	+  /** Left the match: they keep their kit, and cannot eat. */
900	+  readonly left: boolean;
901	+}
902	+
903	+/** One world tick's facts; the order of `players` never matters. A player absent from the list is not holding. */
904	+export interface FruitTickInput {
905	+  /** Must be later than the state's tick; a skipped tick is a gap that resets every channel. */
906	+  readonly tick: number;
907	+  readonly players: readonly FruitPlayer[];
908	+}
909	+
910	+/** Why a held request cannot eat: the player is gone, busy or fed, or the pedestal is empty. */
911	+export type FruitRefusalReason = "left" | "disconnected" | "reserved" | "already-eaten" | "empty";
912	+
913	+/** Why a channel reset to zero. `taken`: another player ate the fruit first (on an earlier completion, or this tick). */
914	+export type FruitInterruptReason = "released" | "moved" | "gap" | "taken" | "left" | "disconnected" | "reserved";
915	+
916	+/** Something that happened on a tick, for the caller to apply or announce; listed in player id order. */
917	+export type FruitResult =
918	+  | { readonly kind: "eat-started"; readonly tick: number; readonly playerId: string; readonly pedestalId: string }
919	+  /** The channel was lost; `held` is the ticks it had. */
920	+  | { readonly kind: "eat-interrupted"; readonly tick: number; readonly playerId: string; readonly pedestalId: string; readonly reason: FruitInterruptReason; readonly held: number }
921	+  /** A request held at a pedestal that cannot start; reported on every tick it is held. */
922	+  | { readonly kind: "eat-refused"; readonly tick: number; readonly playerId: string; readonly pedestalId: string; readonly reason: FruitRefusalReason }
923	+  /** The fruit is eaten: `kit` is the player's kit for the rest of the match. */
924	+  | { readonly kind: "eat-completed"; readonly tick: number; readonly playerId: string; readonly pedestalId: string; readonly kit: FruitKitId }
925	+  /** A tick not later than the state's: nothing is applied and the very same state comes back. */
926	+  | { readonly kind: "tick-rejected"; readonly tick: number; readonly lastTick: number };
927	+
928	+export interface FruitStepResult {
929	+  readonly state: FruitState;
930	+  readonly results: readonly FruitResult[];
931	+}
932	+
933	+/** Lowest id by UTF-16 code units, independent of locale. */
934	+export function compareIds(a: string, b: string): number {
935	+  return a < b ? -1 : a > b ? 1 : 0;
936	+}
937	+
938	+function requireBoolean(value: unknown, name: string): void {
939	+  if (typeof value !== "boolean") throw new RangeError(`${name} must be a boolean, got ${String(value)}`);
940	+}
941	+
942	+/** Refuses malformed facts (a caller bug): duplicate or empty ids, unknown pedestals, non-boolean flags. */
943	+function readPlayers(state: FruitState, input: FruitTickInput): FruitPlayer[] {
944	+  const pedestalIds = new Set(state.pedestals.map((pedestal) => pedestal.id));
945	+  const seen = new Set<string>();
946	+  for (const player of input.players) {
947	+    if (typeof player.playerId !== "string" || player.playerId.length === 0) throw new RangeError("player ids must be non-empty strings");
948	+    if (seen.has(player.playerId)) throw new RangeError(`player ${player.playerId} appears twice`);
949	+    seen.add(player.playerId);
950	+    if (player.pedestalId !== null && !pedestalIds.has(player.pedestalId)) throw new RangeError(`unknown pedestal ${String(player.pedestalId)}`);
