966	+  const players = readPlayers(state, input);
967	+  const tick = input.tick;
968	+  const results: FruitResult[] = [];
969	+  const interrupted = (channel: FruitChannel, reason: FruitInterruptReason): FruitResult => ({
970	+    kind: "eat-interrupted",
971	+    tick,
972	+    playerId: channel.playerId,
973	+    pedestalId: channel.pedestalId,
974	+    reason,
975	+    held: channel.held,
976	+  });
977	+
978	+  const pedestals = new Map(state.pedestals.map((pedestal) => [pedestal.id, pedestal]));
979	+  const fed = new Set(state.meals.map((meal) => meal.playerId));
980	+  const previous = new Map(state.channels.map((channel) => [channel.playerId, channel]));
981	+  const present = new Set(players.map((player) => player.playerId));
982	+  const gap = tick !== state.tick + 1;
983	+
984	+  // Each player's step, and the released channels of absent players, merged in id order.
985	+  const steps: { playerId: string; results: FruitResult[]; channel: FruitChannel | null }[] = [];
986	+  for (const channel of state.channels) {
987	+    if (!present.has(channel.playerId)) steps.push({ playerId: channel.playerId, results: [interrupted(channel, gap ? "gap" : "released")], channel: null });
988	+  }
989	+  for (const player of players) {
990	+    const own: FruitResult[] = [];
991	+    let channel = previous.get(player.playerId) ?? null;
992	+    // 1. A skipped tick breaks every channel.
993	+    if (channel !== null && gap) {
994	+      own.push(interrupted(channel, "gap"));
995	+      channel = null;
996	+    }
997	+    const target = player.holding ? player.pedestalId : null;
998	+    if (target === null) {
999	+      if (channel !== null) own.push(interrupted(channel, "released"));
1000	+      steps.push({ playerId: player.playerId, results: own, channel: null });
1001	+      continue;
1002	+    }
1003	+    if (channel !== null && channel.pedestalId !== target) {
1004	+      own.push(interrupted(channel, "moved"));
1005	+      channel = null;
1006	+    }
1007	+    const pedestal = pedestals.get(target)!;
1008	+    const refusal: FruitRefusalReason | null = player.left
1009	+      ? "left"
1010	+      : player.disconnected
1011	+        ? "disconnected"
1012	+        : player.reserved
1013	+          ? "reserved"
1014	+          : fed.has(player.playerId)
1015	+            ? "already-eaten"
1016	+            : pedestal.eatenBy !== null
1017	+              ? "empty"
1018	+              : null;
1019	+    if (refusal !== null) {
1020	+      // A live channel can only meet the player's own state here: a fed player or an empty pedestal has none.
1021	+      if (channel !== null) own.push(interrupted(channel, refusal as FruitInterruptReason));
1022	+      else own.push({ kind: "eat-refused", tick, playerId: player.playerId, pedestalId: target, reason: refusal });
1023	+      steps.push({ playerId: player.playerId, results: own, channel: null });
1024	+      continue;
1025	+    }
1026	+    if (channel !== null) {
1027	+      channel = { ...channel, lastTick: tick, held: channel.held + 1 };
1028	+    } else {
1029	+      channel = { playerId: player.playerId, pedestalId: target, startTick: tick, lastTick: tick, held: 1 };
1030	+      own.push({ kind: "eat-started", tick, playerId: player.playerId, pedestalId: target });
1031	+    }
1032	+    steps.push({ playerId: player.playerId, results: own, channel });
1033	+  }
1034	+  steps.sort((a, b) => compareIds(a.playerId, b.playerId));
1035	+  for (const step of steps) results.push(...step.results);
1036	+
1037	+  // 2. Completions in id order: the lowest id eats; the rest at that pedestal find it taken.
1038	+  const meals: FruitMeal[] = [...state.meals];
1039	+  let channels = steps.flatMap((step) => (step.channel === null ? [] : [step.channel]));
1040	+  for (const channel of channels) {
1041	+    if (channel.held < config.eatTicks) continue;
1042	+    const pedestal = pedestals.get(channel.pedestalId)!;
1043	+    if (pedestal.eatenBy !== null) continue;
1044	+    pedestals.set(pedestal.id, { ...pedestal, eatenBy: channel.playerId });
1045	+    meals.push({ playerId: channel.playerId, pedestalId: pedestal.id, kit: pedestal.kit, tick });
1046	+    results.push({ kind: "eat-completed", tick, playerId: channel.playerId, pedestalId: pedestal.id, kit: pedestal.kit });
1047	+  }
1048	+  const eatenNow = new Set(meals.slice(state.meals.length).map((meal) => meal.pedestalId));
1049	+  const eaters = new Set(meals.slice(state.meals.length).map((meal) => meal.playerId));
1050	+  channels = channels.filter((channel) => {
1051	+    if (eaters.has(channel.playerId)) return false;
1052	+    if (!eatenNow.has(channel.pedestalId)) return true;
1053	+    results.push(interrupted(channel, "taken"));
1054	+    return false;
1055	+  });
1056	+
1057	+  meals.sort((a, b) => compareIds(a.playerId, b.playerId));
1058	+  const next: FruitState = {
1059	+    tick,
1060	+    pedestals: state.pedestals.map((pedestal) => pedestals.get(pedestal.id)!),
1061	+    channels,
1062	+    meals,
1063	+  };
1064	+  return { state: next, results };
1065	+}
1066	+
1067	+export interface FruitReplay {
1068	+  readonly state: FruitState;
1069	+  readonly results: readonly FruitResult[];
1070	+  readonly hash: string;
1071	+}
1072	+
1073	+/** Steps a sequence of ticks from a state, collecting every result; `hash` is the final state's `hashState`. */
1074	+export function replayFruits(config: FruitConfig, state: FruitState, inputs: readonly FruitTickInput[]): FruitReplay {
1075	+  let current = state;
1076	+  const results: FruitResult[] = [];
1077	+  for (const input of inputs) {
1078	+    const stepped = stepFruits(config, current, input);
1079	+    current = stepped.state;
1080	+    results.push(...stepped.results);
1081	+  }
1082	+  return { state: current, results, hash: hashState(current) };
1083	+}
1084	+
1085	+/** Invariant violations of a fruit state, empty when it is consistent. */
1086	+export function checkFruitState(state: FruitState): string[] {
1087	+  const issues: string[] = [];
1088	+  const pedestals = new Map<string, FruitPedestal>(state.pedestals.map((pedestal) => [pedestal.id, pedestal]));
1089	+  const eatenPedestals = new Set<string>();
1090	+  const fedPlayers = new Set<string>();
1091	+  for (const meal of state.meals) {
1092	+    if (fedPlayers.has(meal.playerId)) issues.push(`player ${meal.playerId} ate twice`);
1093	+    fedPlayers.add(meal.playerId);
1094	+    if (eatenPedestals.has(meal.pedestalId)) issues.push(`pedestal ${meal.pedestalId} was eaten twice`);
1095	+    eatenPedestals.add(meal.pedestalId);
1096	+    const pedestal = pedestals.get(meal.pedestalId);
1097	+    if (pedestal === undefined) issues.push(`meal at unknown pedestal ${meal.pedestalId}`);
1098	+    else if (pedestal.eatenBy !== meal.playerId || pedestal.kit !== meal.kit) issues.push(`pedestal ${meal.pedestalId} disagrees with ${meal.playerId}'s meal`);
1099	+  }
1100	+  const full = state.pedestals.filter((pedestal) => pedestal.eatenBy === null).length;
1101	+  if (state.meals.length + full !== state.pedestals.length) issues.push(`${state.meals.length} meals + ${full} full pedestals != ${state.pedestals.length} pedestals`);
1102	+  for (const channel of state.channels) {
1103	+    if (fedPlayers.has(channel.playerId)) issues.push(`fed player ${channel.playerId} is still eating`);
1104	+    if (pedestals.get(channel.pedestalId)?.eatenBy !== null) issues.push(`channel at empty or unknown pedestal ${channel.pedestalId}`);
1105	+    if (channel.held !== channel.lastTick - channel.startTick + 1) issues.push(`channel of ${channel.playerId} skipped a tick`);
1106	+  }
1107	+  return issues;
1108	+}
